runs.stdout:
is_port true
echo <<"hello world">>
recv timeout {error,timeout}
addresses {{127,0,0,1},{127,0,0,1}}
send closed {error,closed}
recv closed {error,closed}
active once {<<"one">>,none,[<<"two">>,<<"three">>],[tcp_closed]}
server got "ping"
client got [{tcp,"pong"},tcp_closed]
controlling_process ok
owner got <<"to the new owner">>
not owner {true,{error,not_owner}}
old owner {error,not_owner}
accept timeout {error,timeout}
listen in use {error,eaddrinuse}
accept closed {error,closed}
bad option {exit,badarg}
udp {<<"to b">>,<<"to a">>,true,{error,timeout}}
ipv6 {<<"six">>,{0,0,0,0,0,0,0,1}}
done
